// The single source of the visual language. Mobile imports these values; web and admin get the same values as CSS
// custom properties from tokens.css (generated by scripts/generate-css.ts, kept in sync by a test).
// Every colour is a semantic role with a light and a dark value: components name the role, never a hex.

export const colorRoles = [
  'paper', 'surface', 'surfaceContainer', 'neutralSurface', 'line',
  'ink', 'muted',
  'primary', 'onPrimary', 'primaryContainer', 'onPrimaryContainer', 'softPrimary', 'secondaryContainer', 'onSecondaryContainer',
  'success', 'onSuccess', 'softSuccess', 'red', 'onRed', 'softRed', 'warning', 'softWarning',
  'navy', 'onNavy', 'onNavyMuted', 'accent', 'scrim',
] as const;
export type ColorRole = (typeof colorRoles)[number];
export type Palette = Record<ColorRole, string>;

export const lightPalette: Palette = {
  paper: '#F5F7FC', surface: '#FFFFFF', surfaceContainer: '#EDF2FA', neutralSurface: '#E7EDF7', line: '#D7E0ED',
  ink: '#1C2D47', muted: '#52647E',
  primary: '#2459A6', onPrimary: '#FFFFFF', primaryContainer: '#DEE9FC', onPrimaryContainer: '#173968', softPrimary: '#E9F0FD',
  secondaryContainer: '#E8EDF7', onSecondaryContainer: '#2E4262',
  success: '#237A4B', onSuccess: '#FFFFFF', softSuccess: '#EDF5EF', red: '#B9384A', onRed: '#FFFFFF', softRed: '#FBEDEF', warning: '#8A5A00', softWarning: '#FBF1DC',
  navy: '#142D50', onNavy: '#FFFFFF', onNavyMuted: '#C8D9F1', accent: '#D6A64F', scrim: 'rgba(20, 45, 80, 0.48)',
};

// Dark is not an inversion: tinted dark grey instead of black, lighter surfaces for higher elevation,
// desaturated accents that still pass AA on those surfaces, and dark text on the light primary.
export const darkPalette: Palette = {
  paper: '#0C1422', surface: '#141E2E', surfaceContainer: '#1C293D', neutralSurface: '#24324A', line: '#34445E',
  ink: '#E7EEF9', muted: '#A8B7CE',
  primary: '#9EC5FF', onPrimary: '#102E54', primaryContainer: '#213F6B', onPrimaryContainer: '#D4E5FF', softPrimary: '#192F4E',
  secondaryContainer: '#2B3A52', onSecondaryContainer: '#DEE7F6',
  success: '#6FD39A', onSuccess: '#00210F', softSuccess: '#17301F', red: '#F2808F', onRed: '#3A0010', softRed: '#3A1D22', warning: '#E9B84F', softWarning: '#3A2E12',
  navy: '#173763', onNavy: '#FFFFFF', onNavyMuted: '#C8D9F1', accent: '#D6A64F', scrim: 'rgba(0, 0, 0, 0.6)',
};

export type ColorScheme = 'light' | 'dark';
export const palettes: Record<ColorScheme, Palette> = { light: lightPalette, dark: darkPalette };

// What the user chose: follow the device, or force one scheme.
export type ThemePreference = 'system' | 'light' | 'dark';
export const themePreferences: readonly ThemePreference[] = ['system', 'light', 'dark'];
export const themePreferenceLabels: Record<ThemePreference, string> = { system: 'Cihaz ayarı', light: 'Açık', dark: 'Koyu' };
export function resolveScheme(preference: ThemePreference, system: ColorScheme | null | undefined): ColorScheme {
  return preference === 'system' ? (system === 'dark' ? 'dark' : 'light') : preference;
}

// Shapes in px: small chips and inputs, cards, hero surfaces; `full` is a capsule.
export const shape = { small: 8, medium: 16, large: 24, extraLarge: 32, full: 999 } as const;

// Spacing in px. Phones keep content close to the screen edges; larger windows get more air and a reading width.
export const space = { gutterCompact: 14, gutterMedium: 24, gutterExpanded: 32, cardPadding: 14, cardPaddingWide: 20, gap: 12 } as const;

// Window size classes (Material window size classes, in px): compact is a phone, medium a small tablet / foldable,
// expanded a large tablet or desktop.
export const breakpoints = { medium: 600, expanded: 840 } as const;
export type WindowClass = 'compact' | 'medium' | 'expanded';
export const windowClass = (width: number): WindowClass => (width >= breakpoints.expanded ? 'expanded' : width >= breakpoints.medium ? 'medium' : 'compact');
// The widest a reading column (a question, a form) may be; lists and grids use the full width up to `contentMaxWidth`.
export const readingMaxWidth = 720;
export const contentMaxWidth = 1120;

export const typeScale = {
  display: { fontSize: 34, lineHeight: 41, fontWeight: '800', letterSpacing: -1.2 },
  headline: { fontSize: 30, lineHeight: 37, fontWeight: '800', letterSpacing: -0.8 },
  title: { fontSize: 21, lineHeight: 28, fontWeight: '700', letterSpacing: -0.4 },
  body: { fontSize: 17, lineHeight: 27 },
  label: { fontSize: 15, lineHeight: 22, fontWeight: '700' },
  caption: { fontSize: 13, lineHeight: 20 },
} as const;

// Minimum touch target (px); buttons are larger.
export const minTouchTarget = 44;
